//! Parity and regression tests for the bailingmm (Ming Omni TTS)
//! family, dense variant included.
//!
//! Pinned fixtures reside in `testdata/tts_bailingmm/`, generated by
//! `tools/gen_bailingmm_fixtures.py` against mlx-audio 0.5.7 commit
//! `e1b19b9054bf163f5d812221a54fcc346f1890e9` (mlx 0.32.3). The
//! generator runs the true reference modules (the checkpoint tokenizer
//! replaced by a deterministic offline mock), so the traces carry the
//! reference `_prepare_input_embed` ids and embeddings, the
//! `Model.sample` per-step latent patches and stop decisions, the
//! reference decode loop's per-step chunks, the recorded
//! `mx.random.normal` draws (replayed here through the Rust noise
//! source), and the joined waveform.

use std::collections::VecDeque;
use std::path::{Path, PathBuf};

use serde_json::Value;

use super::dit::FlowNoise;
use super::{music_style_text, GenerateParams, MarkerIds, Model, PromptSegments, StopReason};
use crate::tts::bailingmm::dit::FlowParams;

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/tts_bailingmm")
        .join(name)
}

fn read_json(path: &Path) -> Value {
    let text = std::fs::read_to_string(path).expect("fixture json");
    serde_json::from_str(&text).expect("fixture json")
}

fn f32_vec(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| v.as_f64().expect("value") as f32)
        .collect()
}

fn i32_vec(value: &Value) -> Vec<i32> {
    value
        .as_array()
        .expect("ids")
        .iter()
        .map(|v| v.as_i64().expect("id") as i32)
        .collect()
}

fn max_abs_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(
        a.len(),
        b.len(),
        "length mismatch: {} vs {}",
        a.len(),
        b.len()
    );
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max)
}

/// Measured maximum differences when the gates were frozen; assertions
/// use these values, not re-measured ones. The waveform and embedding
/// gates sit above the f32 attention/conv/FFT accumulation order noise;
/// the latent gate covers the solver's Euler accumulation.
const WAVEFORM_TOLERANCE: f32 = 2e-5;
const EMBEDS_TOLERANCE: f32 = 4e-6;
const LATENT_TOLERANCE: f32 = 2e-5;

/// The recorded `mx.random.normal` draws replayed in reference order.
pub(crate) struct ReplayNoise {
    draws: VecDeque<(Vec<usize>, Vec<f32>)>,
}

impl ReplayNoise {
    pub(crate) fn from_trace(traces: &Value) -> Self {
        let draws: Vec<(Vec<usize>, Vec<f32>)> = traces["noise_draws"]
            .as_array()
            .expect("draws")
            .iter()
            .map(|draw| {
                (
                    draw["shape"]
                        .as_array()
                        .expect("shape")
                        .iter()
                        .map(|v| v.as_u64().expect("dim") as usize)
                        .collect::<Vec<_>>(),
                    f32_vec(&draw["values"]),
                )
            })
            .collect();
        Self {
            draws: VecDeque::from(draws),
        }
    }

    pub(crate) fn next_draw(&mut self, shape: [usize; 3]) -> Vec<f32> {
        let (recorded, values) = self
            .draws
            .pop_front()
            .expect("the fixture ran out of recorded draws");
        assert_eq!(
            recorded,
            shape.to_vec(),
            "recorded draw shape does not match the request"
        );
        values
    }
}

impl FlowNoise for ReplayNoise {
    fn flow_noise(&mut self, shape: [usize; 3]) -> Vec<f32> {
        self.next_draw(shape)
    }

    fn solver_noise(&mut self, shape: [usize; 3]) -> Vec<f32> {
        self.next_draw(shape)
    }
}

/// The tokenized prompt segments and marker ids of one recorded case.
struct CaseSegments {
    markers: MarkerIds,
    prompt: Vec<i32>,
    text: Vec<i32>,
}

fn case_segments(traces: &Value) -> CaseSegments {
    let segments = &traces["prompt"]["segments"];
    CaseSegments {
        markers: MarkerIds {
            role_human: i32_vec(&segments["role_human"]),
            text_input_header: i32_vec(&segments["text_input_header"]),
            role_assistant: i32_vec(&segments["role_assistant"]),
            end_of_text: segments["end_of_text"].as_i64().expect("eot") as i32,
            audio_token: segments["audio_token"].as_i64().expect("audio") as i32,
            patch_token: segments["patch_token"].as_i64().expect("patch") as i32,
        },
        prompt: i32_vec(&segments["prompt"]),
        text: i32_vec(&segments["text"]),
    }
}

fn params(traces: &Value) -> GenerateParams {
    GenerateParams {
        cfg_scale: traces["flow"]["cfg"].as_f64().expect("cfg") as f32,
        sigma: traces["flow"]["sigma"].as_f64().expect("sigma") as f32,
        temperature: traces["flow"]["temperature"].as_f64().expect("temp") as f32,
        flow_steps: traces["flow"]["steps"].as_u64().expect("steps") as usize,
        max_decode_steps: 12,
    }
}

/// Drives one case end to end: prompt assembly, per-step latents, and
/// the joined waveform, all against the recorded reference values.
fn run_generation_case(name: &str) {
    let traces = read_json(&testdata(&format!("{name}/traces.json")));
    let mut model = Model::open(&testdata(name)).expect("family model loads");
    let case = case_segments(&traces);
    let segments = PromptSegments {
        prompt: &case.prompt,
        text: &case.text,
        instruction: None,
        prompt_text: None,
        prompt_latent: None,
        skip_text_input_header: false,
    };
    let (embeds, num_patches) = model
        .prepare_input_embeds(&case.markers, &segments)
        .unwrap_or_else(|error| panic!("{name}: prompt assembly failed: {error}"));
    assert_eq!(num_patches, 0, "{name}: unexpected patch count");
    let want_embeds = f32_vec(&traces["prompt"]["input_embeds"]);
    let diff = max_abs_diff(&embeds, &want_embeds);
    assert!(diff <= EMBEDS_TOLERANCE, "{name}: input embeds diff {diff}");

    let mut noise = ReplayNoise::from_trace(&traces);
    let generated = model
        .generate(&embeds, None, &params(&traces), &mut noise)
        .unwrap_or_else(|error| panic!("{name}: generate failed: {error}"));
    assert!(noise.draws.is_empty(), "{name}: draws left unconsumed");

    // Per-step latents and the stop decision.
    let mut want_latents = Vec::new();
    let mut any_last = false;
    for step in traces["steps"].as_array().expect("steps") {
        want_latents.extend(f32_vec(&step["latent"]));
        any_last |= step["is_last"].as_bool().expect("is_last");
    }
    let diff = max_abs_diff(&generated.latents, &want_latents);
    assert!(diff <= LATENT_TOLERANCE, "{name}: latents diff {diff}");
    assert_eq!(
        generated.stopped_by,
        if any_last {
            StopReason::StopHead
        } else {
            StopReason::MaxDecodeSteps
        },
        "{name}: stop reason"
    );
    assert_eq!(
        generated.latent_steps,
        traces["steps"].as_array().expect("steps").len(),
        "{name}: step count"
    );

    let diff = max_abs_diff(&generated.samples, &f32_vec(&traces["waveform"]));
    assert!(diff <= WAVEFORM_TOLERANCE, "{name}: waveform diff {diff}");
    assert_eq!(
        generated.sample_rate as i64,
        traces["sample_rate"].as_i64().expect("rate")
    );
}

/// Stage gates on the raw guide call of the first two solver steps:
/// the assembled block input, the per-block outputs, the full-sequence
/// output, and the guided crop. The block-stage tensors carry the
/// timestep embedding's magnitude (hundreds), so those gates scale with
/// it; the guided latents stay at the O(1) latent gate.
#[test]
fn dit_guide_stages_match_the_reference() {
    let traces = read_json(&testdata("moe_generate/traces.json"));
    let model = Model::open(&testdata("moe_generate")).expect("model loads");
    for (index, call) in traces["dit_calls"]
        .as_array()
        .expect("calls")
        .iter()
        .enumerate()
    {
        let x = f32_vec(&call["x"]);
        let t = call["t"].as_f64().unwrap() as f32;
        let cfg = call["cfg"].as_f64().unwrap() as f32;
        let history = f32_vec(&call["latent_history"]);
        let want = f32_vec(&call["out"]);
        // x2/hist2/c2 doubled: the reference forward_with_cfg doubles
        // inside, the Rust one takes doubled inputs. The cond row is the
        // step's z ([1, 1, hidden]).
        let mut x2 = x.clone();
        x2.extend_from_slice(&x);
        let mut hist2 = history.clone();
        hist2.extend_from_slice(&history);
        // Both recorded guide calls belong to generate step 0 (solver
        // steps 1 and 2), so both read the step-0 z row.
        let z = f32_vec(&traces["flow_steps"][0]["z"]);
        let mut c2 = vec![0.0f32; 2 * z.len()];
        c2[..z.len()].copy_from_slice(&z);
        let (assembled, block_diffs) = model.flowloss.block_probe(&x2, t, &c2, &hist2, 2, 2, 2);
        let want_input = f32_vec(&call["blocks"][0]["input"]);
        let pre_scale = want_input.iter().fold(1.0f32, |m, v| m.max(v.abs()));
        let assembly_diff = max_abs_diff(&assembled, &want_input);
        assert!(
            assembly_diff <= 2e-5 * pre_scale,
            "dit call {index}: assembly diff {assembly_diff} (scale {pre_scale})"
        );
        let want_blocks = call["blocks"].as_array().expect("blocks");
        for (index_block, (block, want)) in block_diffs.iter().zip(want_blocks).enumerate() {
            let want = f32_vec(&want["out"]);
            let scale = want.iter().fold(1.0f32, |m, v| m.max(v.abs()));
            let diff = max_abs_diff(block, &want);
            assert!(
                diff <= 2e-5 * scale,
                "dit call {index}: block {index_block} diff {diff} (scale {scale})"
            );
        }
        let got = model
            .flowloss
            .flowloss_full_probe(&x2, t, &c2, &hist2, 2, 2, 2);
        let want_inner = f32_vec(&call["inner_out"]);
        let diff = max_abs_diff(&got, &want_inner);
        assert!(
            diff <= 2e-5 * pre_scale,
            "dit call {index}: full-sequence diff {diff}"
        );
        let got = model.flowloss_z_probe(&x2, t, &c2, cfg, &hist2, 2, 2, 2);
        // The recorded output is the reference's cropped but UNGUIDED
        // [2, patch, channels]; apply the recorded cfg to its halves and
        // compare with the Rust guided result. This pins the crop
        // layout and the guidance arithmetic.
        let half = want.len() / 2;
        let mut guided = vec![0.0f32; half];
        for i in 0..half {
            guided[i] = want[i] + (want[i] - want[half + i]) * cfg;
        }
        let diff = max_abs_diff(&got, &guided);
        assert!(
            diff <= LATENT_TOLERANCE,
            "dit call {index}: guided diff {diff}"
        );
    }
}

#[test]
fn flow_stack_matches_per_step_reference() {
    let traces = read_json(&testdata("moe_generate/traces.json"));
    let model = Model::open(&testdata("moe_generate")).expect("model loads");
    let flow = FlowParams {
        cfg: traces["flow"]["cfg"].as_f64().unwrap() as f32,
        patch: 2,
        sigma: traces["flow"]["sigma"].as_f64().unwrap() as f32,
        temperature: traces["flow"]["temperature"].as_f64().unwrap() as f32,
        steps: traces["flow"]["steps"].as_u64().unwrap() as usize,
        use_epss: true,
        sway_sampling_coef: -1.0,
    };
    // Per generate step the draw sequence is one flow noise then one
    // solver draw per integration step.
    let draws: Vec<(Vec<usize>, Vec<f32>)> = traces["noise_draws"]
        .as_array()
        .expect("draws")
        .iter()
        .map(|draw| {
            (
                draw["shape"]
                    .as_array()
                    .expect("shape")
                    .iter()
                    .map(|v| v.as_u64().expect("dim") as usize)
                    .collect(),
                f32_vec(&draw["values"]),
            )
        })
        .collect();
    let per_step = 1 + flow.steps;
    for (step, case) in traces["flow_steps"]
        .as_array()
        .expect("flow steps")
        .iter()
        .enumerate()
    {
        let z = f32_vec(&case["z"]);
        let history = f32_vec(&case["latent_history"]);
        let mut noise = ReplayNoise {
            draws: VecDeque::from(draws[step * per_step..(step + 1) * per_step].to_vec()),
        };
        let got = model.flowloss.sample(&z, &history, &flow, &mut noise);
        let want = f32_vec(&case["latent"]);
        let diff = max_abs_diff(&got, &want);
        assert!(
            diff <= LATENT_TOLERANCE,
            "flow step {step} latent diff {diff}"
        );
    }
}

#[test]
fn moe_generation_matches_the_reference_end_to_end() {
    run_generation_case("moe_generate");
}

#[test]
fn moe_generation_stops_at_max_decode_steps() {
    run_generation_case("moe_length");
}

#[test]
fn dense_variant_generation_matches_the_reference() {
    run_generation_case("dense_generate");
}

#[test]
fn dense_variant_forces_the_qwen2_backbone() {
    // The dense/ directory config rides this module: model_type "dense"
    // forces the dense path even when MoE keys are present.
    let config = serde_json::json!({
        "model_type": "dense",
        "llm_config": {
            "model_type": "qwen2",
            "hidden_size": 32,
            "num_hidden_layers": 1,
            "intermediate_size": 32,
            "num_attention_heads": 4,
            "num_key_value_heads": 2,
            "vocab_size": 16,
            "rms_norm_eps": 1e-5,
        },
        "audio_tokenizer_config": {},
        "ditar_config": {},
        "aggregator_config": {},
    });
    let parsed = super::ModelConfig::from_json(&config).unwrap();
    assert!(parsed.dense_variant);
    assert!(!parsed.is_moe());
    // The MoE detection needs every key; the ming_omni_tts default.
    let moe_config = serde_json::json!({
        "model_type": "ming_omni_tts",
        "llm_config": {
            "model_type": "bailing_moe",
            "moe_intermediate_size": 32,
            "num_experts": 4,
            "num_shared_experts": 1,
            "norm_topk_prob": true,
            "num_experts_per_tok": 2,
            "first_k_dense_replace": 1,
        },
        "audio_tokenizer_config": {},
        "ditar_config": {},
        "aggregator_config": {},
    });
    let parsed = super::ModelConfig::from_json(&moe_config).unwrap();
    assert!(!parsed.dense_variant);
    assert!(parsed.is_moe());
    let partial = serde_json::json!({
        "model_type": "ming_omni_tts",
        "llm_config": {"model_type": "bailing_moe", "num_experts": 4},
        "audio_tokenizer_config": {},
        "ditar_config": {},
        "aggregator_config": {},
    });
    let parsed = super::ModelConfig::from_json(&partial).unwrap();
    assert!(!parsed.is_moe(), "partial MoE keys must not route to MoE");
}

#[test]
fn voice_clone_matches_the_reference_end_to_end() {
    let traces = read_json(&testdata("voice_clone/traces.json"));
    let mut model = Model::open(&testdata("voice_clone")).expect("model loads");
    let ref_audio = f32_vec(&traces["voice_clone"]["ref_audio"]);

    // The encoder noise is the first recorded draw, consumed
    // channel-major exactly like the reference [batch, latent, frames]
    // layout (frames = the aggregated patch rows).
    let mut noise = ReplayNoise::from_trace(&traces);
    // The encoder draws at the pre-transpose [batch, latent, frames]
    // shape; frames is the latent row count (before patch aggregation).
    let frames = traces["voice_clone"]["prompt_latent"]
        .as_array()
        .expect("latent")
        .len()
        / model.latent_dim();
    let encode_draw = noise.next_draw([1, model.latent_dim(), frames]);
    let mut cursor = encode_draw.clone();
    let mut encode_noise = || cursor.remove(0);
    let (latent, rows) = model
        .encode_prompt_latent(&ref_audio, &mut encode_noise)
        .expect("encode");
    let diff = max_abs_diff(&latent, &f32_vec(&traces["voice_clone"]["prompt_latent"]));
    assert!(diff <= LATENT_TOLERANCE, "voice-clone latent diff {diff}");
    assert_eq!(
        rows * model.latent_dim(),
        traces["voice_clone"]["prompt_latent"]
            .as_array()
            .expect("latent")
            .len()
    );

    let case = case_segments(&traces);
    let segments = PromptSegments {
        prompt: &case.prompt,
        text: &case.text,
        instruction: None,
        prompt_text: Some(&case.text),
        prompt_latent: Some(&latent),
        skip_text_input_header: false,
    };
    let (embeds, num_patches) = model
        .prepare_input_embeds(&case.markers, &segments)
        .expect("prompt assembly");
    assert_eq!(
        num_patches as i64,
        traces["prompt"]["num_patches"].as_i64().expect("patches")
    );
    let diff = max_abs_diff(&embeds, &f32_vec(&traces["prompt"]["input_embeds"]));
    assert!(diff <= EMBEDS_TOLERANCE, "voice-clone embeds diff {diff}");

    let generated = model
        .generate(&embeds, Some(&latent), &params(&traces), &mut noise)
        .expect("generate");
    let diff = max_abs_diff(&generated.samples, &f32_vec(&traces["waveform"]));
    assert!(
        diff <= WAVEFORM_TOLERANCE,
        "voice-clone waveform diff {diff}"
    );
    assert_eq!(generated.stopped_by, StopReason::StopHead);
}

#[test]
fn music_style_detection_matches_the_reference_rule() {
    assert!(music_style_text(
        "Genre: pop\nMood: happy\nInstrument: piano\nTheme: rain\nDuration: 30s"
    ));
    assert!(!music_style_text("Genre: pop\nMood: happy"));
}

#[test]
fn flow_timestep_grids_match_the_reference() {
    let traces = read_json(&testdata("moe_generate/traces.json"));
    let got = super::dit::get_epss_timesteps(5);
    let sway = super::dit::sway_sampling(&got, -1.0);
    let diff = max_abs_diff(&got, &f32_vec(&traces["flow"]["t_grid"]));
    assert!(diff <= 1e-6, "t grid diff {diff}");
    let diff = max_abs_diff(&sway, &f32_vec(&traces["flow"]["sway_grid"]));
    assert!(diff <= 1e-6, "sway grid diff {diff}");
    // Unsupported step counts fall back to a linspace.
    assert_eq!(
        super::dit::get_epss_timesteps(3),
        vec![0.0, 1.0 / 3.0, 2.0 / 3.0, 1.0]
    );
}

#[test]
fn generate_refuses_a_zero_step_budget() {
    let mut model = Model::open(&testdata("moe_generate")).expect("model loads");
    let traces = read_json(&testdata("moe_generate/traces.json"));
    let case = case_segments(&traces);
    let segments = PromptSegments {
        prompt: &case.prompt,
        text: &case.text,
        instruction: None,
        prompt_text: None,
        prompt_latent: None,
        skip_text_input_header: false,
    };
    let (embeds, _) = model
        .prepare_input_embeds(&case.markers, &segments)
        .unwrap();
    let mut params = params(&traces);
    params.max_decode_steps = 0;
    let error = model
        .generate(&embeds, None, &params, &mut super::dit::SeededNoise::new(0))
        .unwrap_err();
    assert!(
        error.to_string().contains("No audio chunks were generated"),
        "{error}"
    );
}

#[test]
fn family_defaults_match_the_reference_generate() {
    let defaults = GenerateParams::default();
    assert_eq!(defaults.cfg_scale, 2.0);
    assert_eq!(defaults.sigma, 0.25);
    assert_eq!(defaults.temperature, 0.0);
    assert_eq!(defaults.flow_steps, 10);
    assert_eq!(defaults.max_decode_steps, 200);
    // The loaded model reads its config through.
    let model = Model::open(&testdata("moe_generate")).expect("model loads");
    assert_eq!(model.sample_rate(), 24000);
    assert_eq!(model.latent_dim(), 8);
    let flow = FlowParams {
        cfg: 2.0,
        patch: 2,
        sigma: 0.25,
        temperature: 0.0,
        steps: 5,
        use_epss: true,
        sway_sampling_coef: -1.0,
    };
    assert_eq!(flow.patch, 2);
}
